svg.script:
function init(evt) {
  const svg = evt.target;
  const text = svg.getElementById('logoText');
  const dot = svg.getElementById('logoDot');

  const bbox = text.getBBox();
  const r = parseFloat(dot.getAttribute('r'));
  const padding = 6; // gap between text and dot

  const cx = bbox.x + bbox.width + padding + r;
  const cy = bbox.y + bbox.height / 2;

  dot.setAttribute('cx', cx);
  dot.setAttribute('cy', cy);
}
